initJs:
function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistoryData = [];
  let filteredData = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    const users = await window.aivicApi.list(0); // ログインユーザーテーブル
    const userSelect = container.querySelector('#user-filter');
    if (users) {
      users.forEach(user => {
        const option = document.createElement('option');
        option.value = user.ユーザーID;
        option.textContent = user.ユーザー名 || user.ログインID;
        userSelect.appendChild(option);
      });
    }
  }

  // 操作履歴テーブルの再描画
  function renderHistoryRows(rows) {
    const tbody = container.querySelector('#history-tbody');
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageRows = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageRows.map(row => {
      const operationDate = row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '';
      const resultClass = row.処理結果 === '成功' ? 'success' : row.処理結果 === '失敗' ? 'error' : '';

      return `
        <tr data-id="${row.操作履歴ID}">
          <td>${operationDate}</td>
          <td>${row.ユーザー名 || ''}</td>
          <td>${row.操作種別 || ''}</td>
          <td>${row.操作画面 || ''}</td>
          <td>${row.IPアドレス || ''}</td>
          <td><span style="color: ${row.処理結果 === '成功' ? '#4ade80' : row.処理結果 === '失敗' ? '#f87171' : 'var(--text)'}">${row.処理結果 || ''}</span></td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.操作履歴ID}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    renderPagination(rows.length);
  }

  // ページネーション描画
  function renderPagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pagination = container.querySelector('#pagination');

    if (totalPages <= 1) {
      pagination.innerHTML = '';
      return;
    }

    let paginationHTML = '';

    // 前へボタン
    if (currentPage > 1) {
      paginationHTML += `<button class="action-btn secondary" data-page="${currentPage - 1}">前へ</button>`;
    }

    // ページ番号
    const startPage = Math.max(1, currentPage - 2);
    const endPage = Math.min(totalPages, currentPage + 2);

    for (let i = startPage; i <= endPage; i++) {
      const activeClass = i === currentPage ? 'action-btn' : 'action-btn secondary';
      paginationHTML += `<button class="${activeClass}" data-page="${i}">${i}</button>`;
    }

    // 次へボタン
    if (currentPage < totalPages) {
      paginationHTML += `<button class="action-btn secondary" data-page="${currentPage + 1}">次へ</button>`;
    }

    pagination.innerHTML = paginationHTML;
  }

  // 検索・フィルタリング処理
  async function performSearch() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const userFilter = container.querySelector('#user-filter').value;
    const operationTypeFilter = container.querySelector('#operation-type-filter').value;
    const screenSearch = container.querySelector('#screen-search').value.toLowerCase();
    const ipSearch = container.querySelector('#ip-search').value;
    const resultFilter = container.querySelector('#result-filter').value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を入力してください');
      return;
    }

    // IPアドレスバリデーション
    if (ipSearch && !isValidIP(ipSearch)) {
      alert('正しいIPアドレス形式で入力してください');
      return;
    }

    filteredData = allHistoryData.filter(row => {
      // 日付範囲フィルター
      if (startDate && row.操作日時 && new Date(row.操作日時) < new Date(startDate)) return false;
      if (endDate && row.操作日時 && new Date(row.操作日時) > new Date(endDate)) return false;

      // ユーザーフィルター
      if (userFilter && row.ユーザーID !== userFilter) return false;

      // 操作種別フィルター
      if (operationTypeFilter && row.操作種別 !== operationTypeFilter) return false;

      // 画面名・機能名検索
      if (screenSearch && !row.操作画面?.toLowerCase().includes(screenSearch)) return false;

      // IPアドレス検索
      if (ipSearch && row.IPアドレス !== ipSearch) return false;

      // 操作結果フィルター
      if (resultFilter && row.処理結果 !== resultFilter) return false;

      return true;
    });

    currentPage = 1;
    renderHistoryRows(filteredData);

    if (filteredData.length === 0) {
      const tbody = container.querySelector('#history-tbody');
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted);">該当する操作履歴が見つかりませんでした</td></tr>';
      container.querySelector('#pagination').innerHTML = '';
    }
  }

  // IPアドレス形式チェック
  function isValidIP(ip) {
    // IPv4チェック
    const ipv4Regex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    // IPv6チェック（簡易版）
    const ipv6Regex = /^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$|^::1$|^::$/;

    return ipv4Regex.test(ip) || ipv6Regex.test(ip);
  }

  // CSV出力
  function exportToCSV() {
    if (filteredData.length === 0) {
      alert('出力可能なデータがありません');
      return;
    }

    const headers = ['操作日時', 'ユーザー名', '操作種別', '操作画面', 'IPアドレス', '処理結果', '操作内容'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...filteredData.map(row => [
        row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '',
        row.ユーザー名 || '',
        row.操作種別 || '',
        row.操作画面 || '',
        row.IPアドレス || '',
        row.処理結果 || '',
        (row.操作内容 || '').replace(/,/g, '，').replace(/\n/g, ' ')
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `操作履歴_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistoryData.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    const modal = container.querySelector('#detail-modal');
    const content = container.querySelector('#detail-content');

    content.innerHTML = `
      <div style="display: grid; grid-template-columns: 150px 1fr; gap: 12px; line-height: 1.6;">
        <div><strong>操作日時:</strong></div>
        <div>${history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : ''}</div>

        <div><strong>ユーザー名:</strong></div>
        <div>${history.ユーザー名 || ''}</div>

        <div><strong>操作種別:</strong></div>
        <div>${history.操作種別 || ''}</div>

        <div><strong>操作画面:</strong></div>
        <div>${history.操作画面 || ''}</div>

        <div><strong>操作対象テーブル:</strong></div>
        <div>${history.操作対象テーブル || ''}</div>

        <div><strong>操作対象ID:</strong></div>
        <div>${history.操作対象ID || ''}</div>

        <div><strong>IPアドレス:</strong></div>
        <div>${history.IPアドレス || ''}</div>

        <div><strong>ユーザーエージェント:</strong></div>
        <div style="word-break: break-all;">${history.ユーザーエージェント || ''}</div>

        <div><strong>処理結果:</strong></div>
        <div style="color: ${history.処理結果 === '成功' ? '#4ade80' : history.処理結果 === '失敗' ? '#f87171' : 'var(--text)'}">${history.処理結果 || ''}</div>

        <div><strong>エラーメッセージ:</strong></div>
        <div>${history.エラーメッセージ || ''}</div>

        <div><strong>処理時間:</strong></div>
        <div>${history.処理時間 ? history.処理時間 + 'ms' : ''}</div>

        <div><strong>操作内容:</strong></div>
        <div style="white-space: pre-wrap; background: var(--bg-main); padding: 12px; border-radius: 4px; border: 1px solid var(--border);">${history.操作内容 || ''}</div>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // 初期データ読み込み
  async function loadInitialData() {
    const historyData = await window.aivicApi.list(13); // システム操作履歴テーブル
    if (historyData) {
      allHistoryData = historyData;
      filteredData = [...allHistoryData];
      renderHistoryRows(filteredData);
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-search').addEventListener('click', performSearch);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#user-filter').value = '';
    container.querySelector('#operation-type-filter').value = '';
    container.querySelector('#screen-search').value = '';
    container.querySelector('#ip-search').value = '';
    container.querySelector('#result-filter').value = '';

    filteredData = [...allHistoryData];
    currentPage = 1;
    renderHistoryRows(filteredData);
  });

  container.querySelector('#btn-csv-export').addEventListener('click', exportToCSV);

  // ページネーションクリック
  container.querySelector('#pagination').addEventListener('click', (e) => {
    const pageBtn = e.target.closest('[data-page]');
    if (pageBtn) {
      const page = parseInt(pageBtn.dataset.page);
      if (page > 0 && page <= Math.ceil(filteredData.length / itemsPerPage)) {
        currentPage = page;
        renderHistoryRows(filteredData);
      }
    }
  });

  // 詳細ボタンクリック
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // モーダル閉じる
  container.querySelector('#close-modal').addEventListener('click', () => {
    container.querySelector('#detail-modal').classList.add('hidden');
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#detail-modal').addEventListener('click', (e) => {
    if (e.target === container.querySelector('#detail-modal')) {
      container.querySelector('#detail-modal').classList.add('hidden');
    }
  });

  // 初期化
  loadUsers();
  loadInitialData();
}
